    bootstrap.register(ApicuriousSpecies.SAFFRON.mutation(), mutation(bootstrap).withFirst(ApicuriousSpecies.MEADOW.species()).withSecond(ApicuriousSpecies.VALIANT.species()).withChance(0.05f).withOutput(ApicuriousSpecies.SAFFRON.species()).build());
